LogicDefinition.ScriptText:
#load "reference"
using FS.SDK.Components;
using System;
using System.Threading;
using System.Text;
using FS.SDK.Extensibility;
using FS.SDK.Util;

//////////////////////////////////////////////////////////////////////////////////////////////////////////////
//                                                                                                          //
//    Logik:           Grob_GripperAddOn_AnalogValues                                                       //
//                                                                                                          //
//////////////////////////////////////////////////////////////////////////////////////////////////////////////
//
//    Datum            Version        Autor            Beschreibung
//
//    23.06.2026       1.0.1          Egg              Ur Version
//
//============================================================================================================
//
//    SW-Standard      Geprüft        Prüfer           Allgemeine Informationen
//                     
//    FEE              X              Egg              AddOn für Analogwert Rückmeldung für Grob_GripperBasic
/*
//============================================================================================================
//
//    Beschreibung:
//
//    Die Logik wird als AddOn für die Grob_GripperBasic Logik verwendet und gibt statt Bool-Werten
//    Analog-Werte als Feedback an die PLC zurück
//
//============================================================================================================
//
//    Input Slot Values
//    SIM_AddOnStatus               =   Byte, Gripper Status von Hauptlogik
//    PAR_UnclampedValue            =   Word, Analogwert Vorgabe Gelöst
//    PAR_ClampedValue              =   Word, Analogwert Vorgabe Gespannt
//    PAR_ClampedWithPartValue      =   Word, Analogwert Vorgabe Gespannt mit Teil
//    PAR_ClampedWithoutPartValue   =   Word, Analogwert Vorgabe Gespannt ohne Teil
//
//    Output Slot Values
//    PLC_IN_Unclamped_Analog           =   Word, Rückmeldung Greifer gelöst
//    PLC_IN_Clamped_Analog             =   Word, Rückmeldung Greifer gespannt
//    PLC_IN_ClampedWithPart_Analog     =   Word, Rückmeldung Greifer gespannt mit Teil
//    PLC_IN_ClampedWithoutPart_Analog  =   Word, Rückmeldung Greifer gespannt ohne Teil
//
//============================================================================================================
*/
//////////////////////////////////////////////////////////////////////////////////////////////////////////////


#region Read-In Status Byte
//============================================================================================================
// R E A D - I N   S T A T U S   B Y T E 
//============================================================================================================

ConvertFunctions.ByteToBool(SIM_AddOnStatus,
out _statusBit0_unclamped,
out _statusBit1_clamped,
out _statusBit2_clampedWithPart,
out _statusBit3_clampedWithoutPart,
out _statusBit4,
out _statusBit5,
out _statusBit6,
out _statusBit7);


#endregion


#region Werte Schreiben
//============================================================================================================
// W E R T E   S C H R E I B E N   
//============================================================================================================

PLC_IN_Unclamped_Analog             = _statusBit0_unclamped             ? PAR_UnclampedValue : (ushort) 0;
PLC_IN_Clamped_Analog               = _statusBit1_clamped               ? PAR_ClampedValue : (ushort) 0;
PLC_IN_ClampedWithPart_Analog       = _statusBit2_clampedWithPart       ? PAR_ClampedWithPartValue : (ushort) 0;
PLC_IN_ClampedWithoutPart_Analog    = _statusBit3_clampedWithoutPart    ? PAR_ClampedWithoutPartValue : (ushort) 0;


#endregion
